			if err != nil {
				t.Fatalf("parseDate(%q) returned unexpected error: %v", tt.in, err)
			}
			// Equal compares instants only, so check the location separately.
			if !got.Equal(tt.want) {
				t.Errorf("parseDate(%q) = %v, want %v", tt.in, got, tt.want)
			}
			if loc := got.Location(); loc != time.UTC {
				t.Errorf("parseDate(%q) location = %v, want UTC", tt.in, loc)
			}
			if h, m, s := got.Clock(); h != 0 || m != 0 || s != 0 || got.Nanosecond() != 0 {
				t.Errorf("parseDate(%q) time of day = %02d:%02d:%02d.%09d, want midnight",
					tt.in, h, m, s, got.Nanosecond())
			}
		})
	}
}

func TestParseDateInvalid(t *testing.T) {
	tests := []struct {
		name string
		in   string
	}{
		{"empty", ""},
		{"wrong layout", "03/17/2024"},
		{"unpadded month and day", "2024-3-7"},
		{"month out of range", "2024-13-01"},
		{"day out of range for month", "2023-02-29"},
		{"trailing time", "2024-03-17T00:00:00Z"},
		{"trailing whitespace", "2024-03-17 "},
		{"not a date", "tomorrow"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := parseDate(tt.in)
			if err == nil {
				t.Fatalf("parseDate(%q) = %v, want error", tt.in, got)
			}
